from __future__ import annotations

"""Evaluate synthetic metric windows and preview ECS Application Auto Scaling reactions."""

from cloudwatch_models import AlarmDefinition, ScalingPolicy, breaches_threshold, recommended_scale_out_desired
from metric_window import count_missing_in_window, evaluation_window, resolve_datapoint_value

PREVIEW_STATES_AFFECTING_CAPACITY = frozenset({"ALARM", "INSUFFICIENT_DATA"})


def alarm_preview_capacity_signal(state: str) -> str:
    if state not in PREVIEW_STATES_AFFECTING_CAPACITY:
        return "steady"
    if state == "ALARM":
        return "scale_out_candidate"
    return "hold_for_data"


def evaluate_alarm_window(
    alarm: AlarmDefinition,
    datapoints: list[float | None],
    previous_state: str = "OK",
) -> dict[str, object]:
    window = evaluation_window(datapoints, alarm.evaluation_periods)
    breaching_count = 0
    ok_count = 0
    missing_count = count_missing_in_window(window)

    for point in window:
        value = resolve_datapoint_value(point)
        if breaches_threshold(value, alarm.threshold, alarm.comparison_operator):
            breaching_count += 1
        else:
            ok_count += 1

    if alarm.treat_missing_data == "ignore" and missing_count:
        state = previous_state
        reason = f"missing datapoints ignored; keeping previous state {previous_state}"
    elif breaching_count >= alarm.datapoints_to_alarm:
        state = "ALARM"
        reason = f"{breaching_count} datapoints breached threshold {alarm.threshold}"
    else:
        state = "OK"
        reason = f"{ok_count} datapoints were within threshold {alarm.threshold}"

    return {
        "alarm_name": alarm.alarm_name,
        "state": state,
        "breaching_datapoints": breaching_count,
        "ok_datapoints": ok_count,
        "missing_datapoints": missing_count,
        "evaluated_datapoints": len(window),
        "reason": reason,
    }


def preview_scaling_decision(
    alarm_result: dict[str, object],
    policy: ScalingPolicy,
) -> dict[str, object]:
    if alarm_result["state"] == "ALARM":
        recommended = recommended_scale_out_desired(policy)
        action = "scale_out" if recommended > policy.desired_capacity else "at_max_capacity"
    elif alarm_result["state"] == "INSUFFICIENT_DATA":
        recommended = policy.desired_capacity
        action = "hold_for_insufficient_data"
    else:
        recommended = policy.desired_capacity
        action = "no_scale_out"

    return {
        "service_name": policy.service_name,
        "alarm_state": alarm_result["state"],
        "action": action,
        "current_desired_capacity": policy.desired_capacity,
        "recommended_desired_capacity": recommended,
        "reason": alarm_result["reason"],
    }


class CloudWatchAlarmPreview:
    """Composable preview entrypoint for ECS service owners validating alarm math."""

    def __init__(self, alarm: AlarmDefinition, policy: ScalingPolicy) -> None:
        self.alarm = alarm
        self.policy = policy

    def evaluate(self, datapoints: list[float | None], previous_state: str = "OK") -> dict[str, object]:
        alarm_result = evaluate_alarm_window(self.alarm, datapoints, previous_state)
        return preview_scaling_decision(alarm_result, self.policy)

