from __future__ import annotations

from dataclasses import dataclass


VALID_COMPARISONS = {"GreaterThanThreshold", "GreaterThanOrEqualToThreshold"}
VALID_MISSING_TREATMENTS = {"breaching", "notBreaching", "ignore", "missing"}


def breaches_threshold(value: float, threshold: float, comparison_operator: str) -> bool:
    if comparison_operator == "GreaterThanOrEqualToThreshold":
        return value >= threshold
    if comparison_operator == "GreaterThanThreshold":
        return value > threshold
    raise ValueError("unsupported comparison_operator")


def normalize_alarm_name(name: str) -> str:
    stripped = name.strip()
    if not stripped:
        raise ValueError("alarm_name required")
    return stripped


def describe_missing_data_treatment(treat: str) -> str:
    if treat not in VALID_MISSING_TREATMENTS:
        raise ValueError("unsupported treat_missing_data")
    return {
        "breaching": "missing datapoints count as breaching",
        "notBreaching": "missing datapoints count as not breaching",
        "ignore": "missing datapoints preserve the previous alarm state",
        "missing": "all-missing windows yield insufficient data",
    }[treat]


def alarm_summary_line(alarm: AlarmDefinition) -> str:
    return (
        f"{alarm.alarm_name} threshold={alarm.threshold} "
        f"operator={alarm.comparison_operator} periods={alarm.evaluation_periods} "
        f"datapoints_to_alarm={alarm.datapoints_to_alarm} missing={alarm.treat_missing_data}"
    )


def recommended_scale_out_desired(policy: ScalingPolicy) -> int:
    return min(policy.max_capacity, policy.desired_capacity + policy.scale_out_step)


def scaling_action_possible(policy: ScalingPolicy) -> bool:
    return recommended_scale_out_desired(policy) > policy.desired_capacity


@dataclass(frozen=True)
class AlarmDefinition:
    alarm_name: str
    threshold: float
    comparison_operator: str
    evaluation_periods: int
    datapoints_to_alarm: int
    treat_missing_data: str

    def __post_init__(self) -> None:
        if not self.alarm_name.strip():
            raise ValueError("alarm_name required")
        if self.comparison_operator not in VALID_COMPARISONS:
            raise ValueError("unsupported comparison_operator")
        if self.evaluation_periods <= 0:
            raise ValueError("evaluation_periods must be positive")
        if self.datapoints_to_alarm <= 0:
            raise ValueError("datapoints_to_alarm must be positive")
        if self.datapoints_to_alarm > self.evaluation_periods:
            raise ValueError("datapoints_to_alarm cannot exceed evaluation_periods")
        if self.treat_missing_data not in VALID_MISSING_TREATMENTS:
            raise ValueError("unsupported treat_missing_data")

    def required_datapoints(self) -> int:
        return self.evaluation_periods


@dataclass(frozen=True)
class ScalingPolicy:
    service_name: str
    min_capacity: int
    max_capacity: int
    desired_capacity: int
    scale_out_step: int

    def __post_init__(self) -> None:
        if not self.service_name.strip():
            raise ValueError("service_name required")
        if self.min_capacity < 0:
            raise ValueError("min_capacity must be non-negative")
        if self.max_capacity < self.min_capacity:
            raise ValueError("max_capacity must be at least min_capacity")
        if not self.min_capacity <= self.desired_capacity <= self.max_capacity:
            raise ValueError("desired_capacity must be within capacity bounds")
        if self.scale_out_step <= 0:
            raise ValueError("scale_out_step must be positive")

    def headroom(self) -> int:
        return max(0, self.max_capacity - self.desired_capacity)

