from __future__ import annotations

from cloudwatch_models import AlarmDefinition


def resolve_datapoint_value(point: float | None) -> float:
    if point is None:
        return 0.0
    return float(point)


def evaluation_window(datapoints: list[float | None], evaluation_periods: int) -> list[float | None]:
    if evaluation_periods <= 0:
        raise ValueError("evaluation_periods must be positive")
    if not datapoints:
        return []
    return datapoints[-evaluation_periods:]


def count_missing_in_window(window: list[float | None]) -> int:
    return sum(1 for point in window if point is None)


def count_present_in_window(window: list[float | None]) -> int:
    return sum(1 for point in window if point is not None)


def resolved_values_for_audit(window: list[float | None]) -> list[float]:
    return [resolve_datapoint_value(point) for point in window]


def window_minutes_span(period_seconds: int, period_count: int) -> int:
    if period_seconds <= 0:
        raise ValueError("period_seconds must be positive")
    if period_count <= 0:
        raise ValueError("period_count must be positive")
    return period_seconds * period_count // 60


def alarm_window_key(alarm: AlarmDefinition, datapoint_count: int) -> str:
    return f"{alarm.alarm_name}:{datapoint_count}:{alarm.evaluation_periods}"


def describe_window_shape(window: list[float | None]) -> dict[str, int]:
    return {
        "length": len(window),
        "missing": count_missing_in_window(window),
        "present": count_present_in_window(window),
    }


def should_consider_insufficient_data(
    missing_count: int,
    treat_missing: str,
    window_len: int,
) -> bool:
    if treat_missing != "missing":
        return False
    return missing_count == window_len and window_len > 0


def scaling_headroom(policy_desired: int, policy_max: int) -> int:
    return max(0, policy_max - policy_desired)


def clamp_recommended_desired(recommended: int, minimum: int, maximum: int) -> int:
    return max(minimum, min(maximum, recommended))


def preview_action_label(alarm_state: str, recommended: int, desired: int, at_max: bool) -> str:
    if alarm_state == "ALARM":
        if at_max or recommended <= desired:
            return "at_max_capacity"
        return "scale_out"
    if alarm_state == "INSUFFICIENT_DATA":
        return "hold_for_insufficient_data"
    return "no_scale_out"


def merge_preview_reasons(alarm_reason: str, action: str) -> str:
    return f"{alarm_reason}; scaling_action={action}"

